import { ParameterValue, Tool, Command } from "@/components/commandly/types/flat";
import { generateCommand } from "@/components/commandly/utils/flat";
import { Button } from "@/components/ui/button";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";
import { TerminalIcon, CopyIcon, SaveIcon } from "lucide-react";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { toast } from "sonner";

interface GeneratedCommandProps {
  tool: Tool;
  selectedCommand?: Command | null;
  parameterValues: Record<string, ParameterValue>;
  onSaveCommand?: (command: string) => void;
  useLongFlag?: boolean;
  children?: ReactNode;
}

interface GeneratedCommandContextValue {
  generatedCommand: string;
  useLongFlag: boolean;
  setUseLongFlag: (value: boolean) => void;
  supportsFlagPreference: boolean;
  onCopyCommand: () => void;
  onSaveCommand?: (command: string) => void;
}

const GeneratedCommandContext = createContext<GeneratedCommandContextValue | null>(null);

function useGeneratedCommandContext() {
  const context = useContext(GeneratedCommandContext);

  if (!context) {
    throw new Error("GeneratedCommand compound components must be used within GeneratedCommand.");
  }

  return context;
}

function GeneratedCommandRoot({
  tool,
  selectedCommand: providedCommand,
  parameterValues,
  onSaveCommand,
  useLongFlag = false,
  children,
}: GeneratedCommandProps) {
  const [prefersLongFlag, setPrefersLongFlag] = useState(useLongFlag);
  const supportsFlagPreference = useMemo(
    () =>
      tool.parameters.some(
        (parameter) =>
          parameter.parameterType !== "Argument" &&
          Boolean(parameter.shortFlag) &&
          Boolean(parameter.longFlag),
      ),
    [tool.parameters],
  );

  useEffect(() => {
    setPrefersLongFlag(useLongFlag);
  }, [useLongFlag]);

  const generatedCommand = useMemo(
    () =>
      generateCommand(tool, parameterValues, {
        selectedCommand: providedCommand,
        useLongFlag: prefersLongFlag,
      }),
    [tool, parameterValues, providedCommand, prefersLongFlag],
  );

  const copyCommand = useCallback(() => {
    navigator.clipboard.writeText(generatedCommand);
    toast("Command copied!");
  }, [generatedCommand]);

  const contextValue = useMemo(
    () => ({
      generatedCommand,
      useLongFlag: prefersLongFlag,
      setUseLongFlag: setPrefersLongFlag,
      supportsFlagPreference,
      onCopyCommand: copyCommand,
      onSaveCommand,
    }),
    [generatedCommand, prefersLongFlag, supportsFlagPreference, copyCommand, onSaveCommand],
  );

  return (
    <GeneratedCommandContext.Provider value={contextValue}>
      {generatedCommand ? (
        (children ?? (
          <div className="min-w-0 space-y-4">
            <GeneratedCommandOutput />
            <GeneratedCommandActions />
          </div>
        ))
      ) : (
        <GeneratedCommandEmptyState />
      )}
    </GeneratedCommandContext.Provider>
  );
}

function GeneratedCommandToolbar({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex flex-wrap items-center justify-end gap-2", className)}
      {...props}
    />
  );
}

function GeneratedCommandHeader({
  children,
  className,
  ...props
}: ComponentProps<typeof CardHeader>) {
  return (
    <CardHeader
      className={cn("flex flex-row items-center justify-between gap-3 space-y-0", className)}
      {...props}
    >
      <CardTitle className="flex items-center gap-2">
        <TerminalIcon className="h-5 w-5" />
        Generated Command
      </CardTitle>
      {children}
    </CardHeader>
  );
}

function GeneratedCommandFlagPreference({
  className,
  ...props
}: Omit<ComponentProps<typeof Switch>, "checked" | "onCheckedChange">) {
  const { supportsFlagPreference, useLongFlag, setUseLongFlag } = useGeneratedCommandContext();

  if (!supportsFlagPreference) return null;

  return (
    <Label className="shrink-0 gap-2 text-xs text-muted-foreground">
      <span className="font-mono tracking-[0.12em] uppercase">Long flags</span>
      <Switch
        checked={useLongFlag}
        onCheckedChange={setUseLongFlag}
        aria-label="Long flags"
        className={className}
        {...props}
      />
    </Label>
  );
}

function GeneratedCommandOutput({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("overflow-x-auto rounded bg-muted p-4 font-mono text-sm", className)}
      {...props}
    >
      <div className="min-w-max whitespace-nowrap">{generatedCommand}</div>
    </div>
  );
}

function GeneratedCommandActions({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand, onCopyCommand, onSaveCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("flex flex-col gap-2 sm:flex-row", className)}
      {...props}
    >
      <Button
        onClick={onCopyCommand}
        variant="outline"
        className="w-full sm:flex-1"
      >
        <CopyIcon className="mr-2 h-4 w-4" />
        Copy Command
      </Button>
      {onSaveCommand && (
        <Button
          onClick={() => onSaveCommand(generatedCommand)}
          variant="outline"
          className="w-full sm:flex-1"
        >
          <SaveIcon className="mr-2 h-4 w-4" />
          Save Command
        </Button>
      )}
    </div>
  );
}

function GeneratedCommandEmptyState() {
  return (
    <div className="py-8 text-center">
      <TerminalIcon className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
      <p className="text-muted-foreground">Configure parameters to generate the command.</p>
    </div>
  );
}

export const GeneratedCommand = Object.assign(GeneratedCommandRoot, {
  Header: GeneratedCommandHeader,
  Toolbar: GeneratedCommandToolbar,
  FlagPreference: GeneratedCommandFlagPreference,
  Output: GeneratedCommandOutput,
  Actions: GeneratedCommandActions,
  EmptyState: GeneratedCommandEmptyState,
});

export interface ToolInfo {
  /** A brief human-readable description of what the tool does. */
  description?: string;
  /** The version string of the tool (e.g. "1.0.0"). */
  version?: string;
  /** The homepage or documentation URL for the tool. */
  url?: string;
}

export interface Command {
  /** Unique identifier for this command within the tool. */
  key: string;
  /** Key of the parent command; used to represent subcommand nesting. */
  parentCommandKey?: string;
  /** Human-readable display name of the command. */
  name: string;
  /** Brief description of what this command does. */
  description?: string;
  /** Whether this command opens an interactive session or prompt. */
  interactive?: boolean;
  /** Display sort position relative to sibling commands. */
  sortOrder?: number;
}

export interface ParameterEnumValue {
  /** The raw value passed to the CLI for this choice. */
  value: string;
  /** Human-readable label shown to the user for this enum choice. */
  displayName: string;
  /** Description of what this enum value does or represents. */
  description?: string;
  /** Whether this is the default selection when no value is provided. */
  isDefault?: boolean;
  /** Display sort position relative to sibling enum values. */
  sortOrder?: number;
}

export interface ParameterEnumValues {
  /** The list of allowed enum choices. */
  values: ParameterEnumValue[];
  /** Whether the user can select multiple values at once. */
  allowMultiple?: boolean;
  /** Separator character used when joining multiple selected values. */
  separator?: string;
}

export type ParameterValidationType =
  | "min_length"
  | "max_length"
  | "min_value"
  | "max_value"
  | "regex";

export interface ParameterValidation {
  /** Unique identifier for this validation rule. */
  key: string;
  /** The type of validation to apply. */
  validationType: ParameterValidationType;
  /** The value to validate against (e.g. the max length number, or a regex pattern). */
  validationValue: string;
  /** The error message to display when validation fails. */
  errorMessage: string;
}

export type ParameterDependencyType = "requires" | "conflicts_with";

export interface ParameterDependency {
  /** Unique identifier for this dependency rule. */
  key: string;
  /** Key of the parameter that owns this dependency. */
  parameterKey: string;
  /** Key of the parameter this dependency references. */
  dependsOnParameterKey: string;
  /** Whether this parameter requires or conflicts with the referenced parameter. */
  dependencyType: ParameterDependencyType;
  /** Optional value that the referenced parameter must have for this dependency to apply. */
  conditionValue?: string;
}

export type ParameterValue = string | number | boolean | string[];

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ToolMetadata {}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ParameterMetadata {
  /** Arbitrary tags for categorising or filtering parameters. */
  tags?: string[];
}

export type ParameterType = "Flag" | "Option" | "Argument";

export type ParameterDataType = "String" | "Number" | "Boolean" | "Enum";

export interface Parameter {
  /** Unique identifier for this parameter within the tool. */
  key: string;
  /** Human-readable display name of the parameter. */
  name: string;
  /** Key of the command this parameter belongs to; omit for global parameters. */
  commandKey?: string;
  /** Brief description of what this parameter does or accepts. */
  description?: string;
  /** Optional grouping label for organising related parameters in the UI. */
  group?: string;
  /** Additional metadata such as tags. */
  metadata?: ParameterMetadata;
  /** Whether this is a boolean flag, a key-value option, or a positional argument. */
  parameterType: ParameterType;
  /** The data type of the parameter's value. */
  dataType: ParameterDataType;
  /** Whether the user must provide this parameter. */
  isRequired?: boolean;
  /** Whether this parameter can be specified multiple times. */
  isRepeatable?: boolean;
  /** Whether this parameter applies to all commands rather than a single command. */
  isGlobal?: boolean;
  /** The single-character short flag (e.g. "-v"). */
  shortFlag?: string;
  /** The long-form flag or option name (e.g. "--verbose"). */
  longFlag?: string;
  /** Zero-based position index for positional arguments. */
  position?: number;
  /** Display sort position relative to sibling parameters. */
  sortOrder?: number;
  /** Separator character used when the option accepts multiple values in one argument (e.g. ","). */
  arraySeparator?: string;
  /** Separator between key and value for key=value style options (e.g. "="). */
  keyValueSeparator?: string;
  /** Allowed enum choices when dataType is "Enum". */
  enum?: ParameterEnumValues;
  /** Validation rules applied to this parameter's value. */
  validations?: ParameterValidation[];
  /** Dependencies on other parameters (requires or conflicts-with relationships). */
  dependencies?: ParameterDependency[];
}

export type ExclusionType = "mutual_exclusive" | "required_one_of";

export interface ExclusionGroup {
  /** Unique identifier for this exclusion group. */
  key?: string;
  /** Key of the command this exclusion group belongs to; omit for global groups. */
  commandKey?: string;
  /** Human-readable name for this exclusion group. */
  name: string;
  /** Whether parameters in this group are mutually exclusive or one is required. */
  exclusionType: ExclusionType;
  /** Keys of the parameters that participate in this exclusion group. */
  parameterKeys: string[];
}

export interface Tool {
  /** Unique binary name for the tool that it can be invoked from the command line (e.g. "httpx"). */
  binaryName: string;
  /** Human-readable display name for the tool (e.g. "HTTPx"). */
  displayName: string;
  /** Whether the root tool invocation opens an interactive session or prompt. */
  interactive?: boolean;
  /** General information about the tool such as description, version, and URL. */
  info?: ToolInfo;
  /** List of all commands and subcommands defined for this tool. */
  commands: Command[];
  /** Flat list of all parameters across all commands and global scope. */
  parameters: Parameter[];
  /** Groups of parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: ExclusionGroup[];
  /** Arbitrary metadata attached to the tool. */
  metadata?: ToolMetadata;
}

import type {
  ExclusionType,
  ParameterDataType,
  ParameterDependencyType,
  ParameterEnumValues,
  ParameterMetadata,
  ParameterType,
  ParameterValidationType,
  ToolInfo,
  ToolMetadata,
} from "@/components/commandly/types/flat";

export interface NestedParameterValidation {
  /** The type of validation to apply. */
  validationType: ParameterValidationType;
  /** The value to validate against (e.g. max length number or regex pattern). */
  validationValue: string;
  /** The error message to display when validation fails. */
  errorMessage: string;
}

export interface NestedParameterDependency {
  /** Name of the parameter this dependency references. */
  dependsOnParameter: string;
  /** Whether this parameter requires or conflicts with the referenced parameter. */
  dependencyType: ParameterDependencyType;
  /** Optional value that the referenced parameter must have for this dependency to apply. */
  conditionValue?: string;
}

export interface NestedParameter {
  /** Human-readable display name of the parameter. */
  name: string;
  /** Brief description of what this parameter does or accepts. */
  description?: string;
  /** Optional grouping label for organising related parameters in the UI. */
  group?: string;
  /** Whether this is a boolean flag, a key-value option, or a positional argument. */
  parameterType: ParameterType;
  /** The data type of the parameter's value. */
  dataType: ParameterDataType;
  /** Additional metadata such as tags. */
  metadata?: ParameterMetadata;
  /** Whether the user must provide this parameter. */
  isRequired?: boolean;
  /** Whether this parameter can be specified multiple times. */
  isRepeatable?: boolean;
  /** Whether this parameter applies to all commands rather than a single command. */
  isGlobal?: boolean;
  /** The single-character short flag (e.g. "-v"). */
  shortFlag?: string;
  /** The long-form flag or option name (e.g. "--verbose"). */
  longFlag?: string;
  /** Zero-based position index for positional arguments. */
  position?: number;
  /** Display sort position relative to sibling parameters. */
  sortOrder?: number;
  /** Separator character used when the option accepts multiple values in one argument (e.g. ","). */
  arraySeparator?: string;
  /** Separator between key and value for key=value style options (e.g. "="). */
  keyValueSeparator?: string;
  /** Allowed enum choices when dataType is "Enum". */
  enum?: ParameterEnumValues;
  /** Validation rules applied to this parameter's value. */
  validations?: NestedParameterValidation[];
  /** Dependencies on other parameters (requires or conflicts-with relationships). */
  dependencies?: NestedParameterDependency[];
}

export interface NestedCommand {
  /** Human-readable display name of the command. */
  name: string;
  /** Brief description of what this command does. */
  description?: string;
  /** Whether this command opens an interactive session or prompt. */
  interactive?: boolean;
  /** Display sort position relative to sibling commands. */
  sortOrder?: number;
  /** Parameters that belong directly to this command. */
  parameters: NestedParameter[];
  /** Nested subcommands of this command. */
  subcommands: NestedCommand[] /** Groups of parameters with mutual exclusion or required-one-of constraints scoped to this command. */;
  exclusionGroups?: NestedExclusionGroup[];
}

export interface NestedExclusionGroup {
  /** Human-readable name for this exclusion group. */
  name: string;
  /** Whether parameters in this group are mutually exclusive or one is required. */
  exclusionType: ExclusionType;
  /** Names of the parameters that participate in this exclusion group. */
  parameters: string[];
}

export interface NestedTool {
  /** Unique binary name for the tool that it can be invoked from the command line (e.g. "httpx"). */
  binaryName: string;
  /** Human-readable display name for the tool (e.g. "HTTPx"). */
  displayName: string;
  /** Whether the root tool invocation opens an interactive session or prompt. */
  interactive?: boolean;
  /** General information about the tool such as description, version, and URL. */
  info?: ToolInfo;
  /** The homepage or documentation URL for the tool. */
  url?: string;
  /** Parameters that belong to the root invocation when no commands exist. */
  rootParameters: NestedParameter[];
  /** Parameters that apply to all commands globally. */
  globalParameters: NestedParameter[];
  /** Hierarchical list of commands and their nested subcommands. */
  commands: NestedCommand[];
  /** Groups of parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: NestedExclusionGroup[] | null;
  /** Arbitrary metadata attached to the tool. */
  metadata?: ToolMetadata;
}

import { SCHEMA_URL } from "@/components/ai-chat/tool-rules";
import type {
  Command,
  ExclusionGroup,
  Parameter,
  ParameterMetadata,
  ParameterValue,
  Tool,
} from "@/components/commandly/types/flat";

export const slugify = (text: string): string => {
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-") // Replace spaces with -
    .replace(/[^\w-]+/g, "") // Remove all non-word chars
    .replace(/--+/g, "-") // Replace multiple - with single -
    .replace(/^-+/, "") // Trim - from start of text
    .replace(/-+$/, ""); // Trim - from end of text
};

export const getCommandPath = (command: Command, tool: Tool): string => {
  const allCommands = tool.commands;
  const findCommandPath = (
    targetKey: string,
    commands: Command[],
    path: string[] = [],
  ): string[] | null => {
    for (const cmd of commands) {
      if (cmd.name === targetKey) {
        return [...path, cmd.name];
      }

      const childCommands = allCommands.filter((c) => c.parentCommandKey === cmd.key);
      if (childCommands.length > 0) {
        const subPath = findCommandPath(targetKey, childCommands, [...path, cmd.name]);
        if (subPath) {
          return subPath;
        }
      }
    }
    return null;
  };

  const rootCommands = tool.commands.filter((c) => !c.parentCommandKey);
  const path = findCommandPath(command.name, rootCommands);

  if (!path) return command.name;

  return path.join(" ");
};

export const getAllSubcommands = (commandKey: string, commands: Command[]): Command[] => {
  const result: Command[] = [];

  const findSubcommands = (parentKey: string) => {
    commands.forEach((cmd) => {
      if (cmd.parentCommandKey === parentKey) {
        result.push(cmd);
        findSubcommands(cmd.key);
      }
    });
  };

  findSubcommands(commandKey);
  return result;
};

export interface GenerateCommandOptions {
  selectedCommand?: Command | null;
  useLongFlag?: boolean;
}

function getPreferredFlag(param: Parameter, useLongFlag: boolean): string | undefined {
  return useLongFlag ? param.longFlag || param.shortFlag : param.shortFlag || param.longFlag;
}

export function generateCommand(
  tool: Tool,
  parameterValues: Record<string, ParameterValue>,
  options: GenerateCommandOptions = {},
): string {
  const hasCommands = tool.commands.length > 0;
  const selectedCommand =
    options.selectedCommand === undefined ? (tool.commands[0] ?? null) : options.selectedCommand;
  const useLongFlag = options.useLongFlag ?? false;

  let command = tool.binaryName;

  if (hasCommands && selectedCommand) {
    const commandPath = getCommandPath(selectedCommand, tool);
    if (tool.binaryName !== commandPath) {
      command = `${tool.binaryName} ${commandPath}`;
    }
  }

  const parametersWithValues: Array<{
    param: Parameter;
    value: ParameterValue;
  }> = [];
  const globalParameters = tool.parameters?.filter((param) => param.isGlobal) ?? [];
  const rootParameters =
    hasCommands && selectedCommand
      ? []
      : (tool.parameters?.filter((param) => !param.commandKey && !param.isGlobal) ?? []);
  const currentParameters = selectedCommand
    ? (tool.parameters?.filter(
        (param) => param.commandKey === selectedCommand.key && !param.isGlobal,
      ) ?? [])
    : [];

  [...globalParameters, ...rootParameters, ...currentParameters].forEach((param) => {
    const value = parameterValues[param.key];
    if (value !== undefined && value !== "" && value !== false) {
      parametersWithValues.push({ param, value });
    }
  });

  const positionalParams = parametersWithValues
    .filter(({ param }) => param.parameterType === "Argument")
    .sort((a, b) => (a.param.position || 0) - (b.param.position || 0));

  parametersWithValues.forEach(({ param, value }) => {
    if (param.parameterType === "Flag") {
      if (value === true) {
        const flag = getPreferredFlag(param, useLongFlag);
        if (flag) command += ` ${flag}`;
      } else if (param.isRepeatable && typeof value === "number" && value > 0) {
        const flag = getPreferredFlag(param, useLongFlag);
        if (flag) command += ` ${flag}`.repeat(value);
      }
      return;
    }

    if (param.parameterType === "Option") {
      const flag = getPreferredFlag(param, useLongFlag);
      if (!flag) return;

      const separator = param.keyValueSeparator ?? " ";
      if (Array.isArray(value)) {
        const entries = value.filter((entry) => entry !== "");
        if (entries.length === 0) return;

        if (param.arraySeparator) {
          command += ` ${flag}${separator}${entries.join(param.arraySeparator)}`;
          return;
        }

        entries.forEach((entry) => {
          command += ` ${flag}${separator}${entry}`;
        });
        return;
      }

      command += ` ${flag}${separator}${value}`;
    }
  });

  positionalParams.forEach(({ value }) => {
    if (!Array.isArray(value)) {
      command += ` ${value}`;
    }
  });

  return command;
}

export const exportToStructuredJSON = (tool: Tool) => {
  return {
    $schema: SCHEMA_URL,
    name: tool.binaryName,
    displayName: tool.displayName,
    info: tool.info,
    commands: tool.commands.map((cmd) => ({ ...cmd })),
    parameters: tool.parameters.map(({ metadata: _metadata, ...param }) => param),
    exclusionGroups: tool.exclusionGroups,
    metadata: tool.metadata,
  };
};

function isEmptyArray(value: unknown): boolean {
  return Array.isArray(value) && value.length === 0;
}

function isEmptyObject(value: unknown): boolean {
  return (
    value != null &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === 0
  );
}

function cleanParameter(param: Parameter): Parameter {
  const cleaned = { ...param };

  if (cleaned.isRequired === false) delete cleaned.isRequired;
  if (cleaned.isRepeatable === false) delete cleaned.isRepeatable;
  if (cleaned.isGlobal === false) delete cleaned.isGlobal;
  if (cleaned.keyValueSeparator === " ") delete cleaned.keyValueSeparator;
  if (cleaned.arraySeparator === "," && cleaned.isRepeatable !== true)
    delete cleaned.arraySeparator;

  if (!cleaned.enum || isEmptyArray(cleaned.enum.values)) delete cleaned.enum;
  if (isEmptyArray(cleaned.validations)) delete cleaned.validations;
  if (isEmptyArray(cleaned.dependencies)) delete cleaned.dependencies;

  if (cleaned.metadata) {
    const meta = { ...cleaned.metadata } as ParameterMetadata;
    if (isEmptyArray(meta.tags)) delete meta.tags;
    if (isEmptyObject(meta)) {
      delete cleaned.metadata;
    } else {
      cleaned.metadata = meta;
    }
  }

  return cleaned;
}

function cleanCommand(cmd: Command): Command {
  const cleaned = { ...cmd };
  if (cleaned.interactive === false) delete cleaned.interactive;
  return cleaned;
}

function cleanExclusionGroup(group: ExclusionGroup): ExclusionGroup {
  return { ...group };
}

export interface FixToolOptions {
  addSchema?: boolean;
  removeMetadata?: boolean;
}

export function fixTool(tool: Tool, options?: FixToolOptions): Tool {
  const addSchema = options?.addSchema ?? false;
  const removeMetadata = options?.removeMetadata ?? false;

  const cleaned: Record<string, unknown> = { ...tool };

  if (addSchema) {
    cleaned["$schema"] = SCHEMA_URL;
  }

  if (cleaned.interactive === false) delete cleaned.interactive;
  if (isEmptyObject(cleaned.metadata) || removeMetadata) delete cleaned.metadata;
  if (isEmptyArray(cleaned.exclusionGroups)) delete cleaned.exclusionGroups;

  if ("description" in cleaned && cleaned.info == null) {
    cleaned.info = { description: cleaned.description as string };
    delete cleaned.description;
  }

  if ("version" in cleaned && typeof cleaned.version === "string") {
    if (cleaned.info && typeof cleaned.info === "object") {
      (cleaned.info as Record<string, unknown>).version = cleaned.version;
    } else {
      cleaned.info = { version: cleaned.version as string };
    }
    delete cleaned.version;
  }

  if (Array.isArray(cleaned.commands)) {
    cleaned.commands = (cleaned.commands as Command[]).map(cleanCommand);
  }

  if (Array.isArray(cleaned.parameters)) {
    cleaned.parameters = (cleaned.parameters as Parameter[]).map((p) => {
      const fixed = cleanParameter(p);
      if (removeMetadata) delete fixed.metadata;
      return fixed;
    });
  }

  if (
    Array.isArray(cleaned.exclusionGroups) &&
    (cleaned.exclusionGroups as ExclusionGroup[]).length > 0
  ) {
    cleaned.exclusionGroups = (cleaned.exclusionGroups as ExclusionGroup[]).map(
      cleanExclusionGroup,
    );
  }

  return cleaned as unknown as Tool;
}

import type { Tool, Command, Parameter } from "@/components/commandly/types/flat";
import {
  NestedCommand,
  NestedExclusionGroup,
  NestedParameter,
  NestedTool,
} from "@/components/commandly/types/nested";

export const convertToNestedStructure = (tool: Tool): NestedTool => {
  const globalParameters = tool.parameters.filter((p) => p.isGlobal);

  const convertParameter = (param: Parameter): NestedParameter => {
    const { ...rest } = param;
    return {
      ...rest,
      validations: param.validations?.map((v) => {
        return {
          validationType: v.validationType,
          validationValue: v.validationValue,
          errorMessage: v.errorMessage,
        };
      }),
      metadata: param.metadata,
      dataType: param.dataType,
      dependencies: param.dependencies?.map((dep) => {
        const dependsOnParam = tool.parameters.find((p) => p.key === dep.dependsOnParameterKey);
        return {
          dependsOnParameter: dependsOnParam?.longFlag || "",
          dependencyType: dep.dependencyType,
          conditionValue: dep.conditionValue,
        };
      }),
    };
  };

  const buildNestedCommands = (commands: Command[], parentKey?: string): NestedCommand[] => {
    return commands
      .filter((cmd) => cmd.parentCommandKey === parentKey)
      .map((cmd) => {
        const commandParameters = tool.parameters.filter(
          (p) => p.commandKey === cmd.key && !p.isGlobal,
        );
        const commandExclusionGroups = tool.exclusionGroups
          ?.filter((g) => g.commandKey === cmd.key)
          .map((group) => ({
            name: group.name,
            exclusionType: group.exclusionType,
            parameters: group.parameterKeys.map((pk) => {
              const param = tool.parameters.find((p) => p.key === pk);
              return param?.longFlag || "";
            }),
          }));
        return {
          name: cmd.name,
          description: cmd.description,
          interactive: cmd.interactive,
          sortOrder: cmd.sortOrder ?? 0,
          parameters: commandParameters.map(convertParameter),
          subcommands: buildNestedCommands(commands, cmd.key),
          ...(commandExclusionGroups?.length ? { exclusionGroups: commandExclusionGroups } : {}),
        };
      });
  };

  const nestedExclusionGroups: NestedExclusionGroup[] | undefined = tool.exclusionGroups
    ?.filter((g) => !g.commandKey)
    .map((group) => ({
      name: group.name,
      exclusionType: group.exclusionType,
      parameters: group.parameterKeys.map((pk) => {
        const param = tool.parameters.find((p) => p.key === pk);
        return param?.longFlag || "";
      }),
    }));

  const rootParameters =
    tool.commands.length === 0 ? tool.parameters.filter((p) => !p.commandKey && !p.isGlobal) : [];

  return {
    binaryName: tool.binaryName,
    url: tool.info?.url,
    displayName: tool.displayName,
    interactive: tool.interactive,
    info: tool.info,
    metadata: tool.metadata,
    rootParameters: rootParameters.map(convertParameter),
    globalParameters: globalParameters.map(convertParameter),
    commands: buildNestedCommands(tool.commands),
    exclusionGroups: nestedExclusionGroups,
  };
};
